let lang = "fr";
try {
  const q = new URLSearchParams(location.search).get("lang");
  lang = dict[q] ? q : dict[localStorage.getItem("lang")] ? localStorage.getItem("lang") : "fr";
} catch { /* storage unavailable */ }

export const getLang = () => lang;
export function setLang(l) {
  lang = dict[l] ? l : "fr";
  try { localStorage.setItem("lang", lang); } catch { /* ignore */ }
  document.documentElement.lang = lang;
}
export const t = (key) => dict[lang][key] ?? dict.fr[key] ?? key;
export const locale = () => (lang === "fr" ? "fr-CA" : "en-CA");
// Role names come from the API as name_fr / name_en.
// One emoji per role (matched on the English role name); unknown roles fall back to their department's icon.
const ROLE_ICONS = { "dishwasher": "🍽️", "cook": "🍕", "chef": "👨‍🍳", "prep cook": "🔪", "delivery driver": "🚗", "waiter / waitress": "🍴", "host / hostess": "🛎️", "busboy / busgirl": "🥤", "runner": "🏃", "assistant cook": "🍕", "manager": "🧑‍💼", "assistant manager": "📋", "office": "🗂️", "owner": "👑" };
const DEPT_ICONS = { floor: "🍴", kitchen: "🍕", prep: "🔪", delivery: "🚗", admin: "🗂️" };
export const deptIcon = (d) => DEPT_ICONS[d] ?? "•";
export const roleIcon = (r) => ROLE_ICONS[(r?.name_en ?? "").toLowerCase()] ?? DEPT_ICONS[r?.department_id] ?? "•";
// Role name in the employee's gender when known ("Cuisinière"), both forms otherwise ("Cuisinier / cuisinière").
export const roleName = (r, sex) => genderedRole(lang === "fr" ? r.name_fr : r.name_en, sex === undefined ? r.sex : sex);
document.documentElement.lang = lang;
